data.forEach(function(d, i){ if (i === n-1) return; var bl = xS(i) - barW/2, br = xS(i) + barW/2; if (br < pillX || bl > pillX + pillW) return; var bot = Math.max(yp(0), yp(d[1])); if (bot > clearY) clearY = bot; });
var pillY = Math.max(lastTip - pillH/2, clearY + 10);
if (pillY + pillH > MT + PH) pillY = MT + PH - pillH;
