svg.appendChild(txt("12 OF 22 SESSIONS BEYOND PLUS OR MINUS 2%", {x: margin.left, y: MT + PH + 36, "text-anchor": "start", "font-size": 7.5, fill: "#888888", "font-family": FS}));
