var pillX = lastX - pillW - 8;
if (pillX < margin.left) pillX = margin.left;
var pillY = lastY - pillH/2;
if (pillY < MT) pillY = MT;
if (pillY + pillH > MT + PH) pillY = MT + PH - pillH;
