VALUES (
  '2026/08/05/tsx-575-points-materials-surge-energy-diverges',
  'market',
  'article',
  'TSX Closes Up 575 Points, Its Best Session in Weeks, as Precious Metals Miners and Energy Producers Move in Opposite Directions',
  'The composite gained 1.63% Tuesday on Hormuz optimism, but the sector-level data shows two different markets trading inside the same session: materials up 4.7% on a safe-haven gold rally, energy down as WTI fell 6.36% on the identical headline.',
  '<ul>
<li><strong>The TSX closed up 575.45 points, 1.63%, at 35,801.59,</strong><span> its strongest session in weeks, as WTI crude fell 6.36% on the same Hormuz headline.</span></li>
<li><strong>Materials led all sectors at plus 4.7%,</strong><span> with Americas Gold and Silver finishing up 18.2%, the index''s top performer.</span></li>
<li><strong>Energy producers moved the opposite direction,</strong><span> with Vermilion Energy down 6.65% and Suncor Energy down 3.19% on the same session.</span></li>
<li><strong>Gold rose to a $4,152.60 close even as equities rallied on de-escalation,</strong><span> an unusual pairing that suggests the market priced reduced tail risk, not removed risk.</span></li>
<li><strong>5N Plus fell 10.07% on second-quarter results,</strong><span> and Telus lost roughly 2% on broker downgrades, both unrelated to the Hormuz headline.</span></li>
</ul>',
  '<p>The S&amp;P/TSX composite closed up 575.45 points, 1.63%, at 35,801.59 Tuesday, on track by midday for its biggest one-day gain in over a month, Reuters reported. WTI crude fell 6.36% the same session. Both moves were driven by the same Hormuz headline. The index-level number hides that they did not move the same stocks.</p>
<h2>Two Trades Inside One Green Day</h2>
<p>Materials advanced 4.7%, the TSX''s strongest sector, led by precious metals miners: Americas Gold and Silver, Trekor Metals and Perpetua Resources each gained between 10.6% and 13.1% intraday, with Americas Gold and Silver finishing the session up 18.2%, the index''s single best performer. Spot gold rose $48.60 to $4,139.10 intraday before extending to a $62.10 gain and a $4,152.60 close, silver climbed roughly 2.4%, and platinum gained over 6%.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">TSX COMPOSITE: TUESDAY&#8217;S BIGGEST MOVERS</span>
<span style="font-size:20px;font-weight:700;color:#111;">35,801.59</span>
<span style="font-size:13px;color:#2e7d32;">&#9650; 1.63%</span>
<span style="font-size:11px;color:#888;margin-left:auto;">DAILY &nbsp;|&nbsp; AUGUST 4, 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
function txt(s, attrs){ return el("text", attrs, s); }
var FS = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
var data = [["Americas Gold|and Silver",18.20],["MDA Space",15.60],["Trekor Metals",14.48],["Aya Gold and Silver",14.23],["Perpetua Resources",13.46],["Baytex Energy",-5.32],["Brookfield|Business Corp",-5.71],["Bausch Health",-6.64],["Vermilion Energy",-6.65],["5N Plus",-10.07]];
var n = data.length;
var margin = {left:110, right:24, top:18, bottom:46};
var PW = 680 - margin.left - margin.right;
var PH = 300 - margin.top - margin.bottom;
var MT = margin.top;
var vals = data.map(function(d){ return d[1]; });
var dMin = Math.min.apply(null, vals), dMax = Math.max.apply(null, vals);
var pad = 0.12 * (dMax - dMin);
var xMin = dMin - pad, xMax = dMax + pad;
var xs = function(v){ return margin.left + (v - xMin) / (xMax - xMin) * PW; };
var gap = 4;
var barH = Math.floor((PH - (n-1) * gap) / n);
var yRow = function(i){ return MT + i * (barH + gap); };
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var ticks = [-10, -5, 0, 5, 10, 15];
ticks.forEach(function(t){ svg.appendChild(el("line", {x1: xs(t), x2: xs(t), y1: MT, y2: MT + PH, stroke: "#ececec", "stroke-width": 0.5})); });
var zeroX = xs(0);
data.forEach(function(d, i){
  var v = d[1];
  var y0 = yRow(i);
  var barX1 = xs(v);
  var x = Math.min(zeroX, barX1), w = Math.abs(barX1 - zeroX);
  svg.appendChild(el("rect", {x: x, y: y0, width: w, height: barH, fill: v >= 0 ? "#3a7a55" : "#8a3030"}));
  var labelLines = d[0].split("|");
  if (labelLines.length === 1) {
    svg.appendChild(txt(labelLines[0], {x: margin.left - 6, y: y0 + barH/2 + 3, "text-anchor": "end", "font-size": 8, fill: "#444444", "font-family": FS}));
  } else {
    svg.appendChild(txt(labelLines[0], {x: margin.left - 6, y: y0 + barH/2 - 2, "text-anchor": "end", "font-size": 8, fill: "#444444", "font-family": FS}));
    svg.appendChild(txt(labelLines[1], {x: margin.left - 6, y: y0 + barH/2 + 8, "text-anchor": "end", "font-size": 8, fill: "#444444", "font-family": FS}));
  }
  var isPos = v >= 0;
  var lx = isPos ? barX1 + 6 : barX1 - 6;
  var anchor = isPos ? "start" : "end";
  svg.appendChild(txt((v > 0 ? "+" : "") + v.toFixed(1) + "%", {x: lx, y: y0 + barH/2 + 3, "text-anchor": anchor, "font-size": 8, "font-weight": 700, fill: v >= 0 ? "#2e7d32" : "#8a3030", "font-family": FS}));
});
svg.appendChild(el("line", {x1: zeroX, x2: zeroX, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
ticks.forEach(function(t){ svg.appendChild(txt((t > 0 ? "+" : "") + t + "%", {x: xs(t), y: MT + PH + 16, "text-anchor": "middle", "font-size": 8, fill: "#999999", "font-family": FS})); });
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: MarketScreener/Reuters, S&amp;P/TSX Composite session rankings, August 4, 2026. &nbsp;|&nbsp; hdq.ca</div>
